def transform(grid):
    from collections import Counter
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == dc == 0:
                        continue
                    r2, c2 = r + dr, c + dc
                    if not (0 <= r2 < h and 0 <= c2 < w):
                        continue
                    if grid[r2][c2] != color:
                        continue
                    # Continue the adjacent pair's direction beyond its second cell.
                    rr, cc = r2 + dr, c2 + dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] == background:
                            out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out
